<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {api,query,errorMessage} from '../api/http'
const router=useRouter(),form=reactive({model:'',type:'',basis:''}),rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false)
async function load(){loading.value=true;try{const data=await api<any>('/containers?'+query({...form,page:page.value-1}));rows.value=data.rows;total.value=data.total}catch(e){ElMessage.error(errorMessage(e))}finally{loading.value=false}}
onMounted(load)
</script>
<template><h1 class="page-title">コンテナ実績</h1><div class="banner">数量は出典区分を確認してください。DOCUMENTED は書類記載値、ACTUAL は実績確認済みです。</div><section class="panel"><header class="panel-heading">検索条件</header><div class="panel-body"><el-form inline><el-form-item label="型番"><el-input v-model="form.model" placeholder="SPG-X"/></el-form-item><el-form-item label="箱種"><el-input v-model="form.type" placeholder="20DRY"/></el-form-item><el-form-item label="記録根拠"><el-select v-model="form.basis" style="width:165px"><el-option label="すべて" value=""/><el-option label="PLANNED" value="PLANNED"/><el-option label="DOCUMENTED" value="DOCUMENTED"/><el-option label="ACTUAL" value="ACTUAL"/></el-select></el-form-item><el-button type="primary" @click="page=1;load()">検索</el-button></el-form></div></section><section class="panel"><header class="panel-heading">履歴一覧（{{total}} 件）</header><div class="panel-body"><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="export_no" label="輸出No."/><el-table-column prop="models" label="型番"/><el-table-column prop="customer_name" label="取引先"/><el-table-column prop="container_type" label="箱種"/><el-table-column prop="container_qty" label="数量" width="70"/><el-table-column prop="record_basis" label="根拠"/><el-table-column label="操作" width="90"><template #default="s"><el-button size="small" @click="router.push('/exports/'+s.row.export_id)">詳細</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" style="margin-top:16px;justify-content:end" layout="prev,pager,next" :total="total" :page-size="20" @current-change="load"/></div></section></template>
